package javax.microedition.lcdui;
public class ChoiceGroup extends Item implements Choice {
 private final List choices;
 public ChoiceGroup(String label,int type){super(label);if(type!=EXCLUSIVE&&type!=MULTIPLE&&type!=POPUP)throw new IllegalArgumentException();choices=new List(label,type==POPUP?EXCLUSIVE:type);}
 public ChoiceGroup(String label,int type,String[] strings,Image[] images){this(label,type);if(strings==null)throw new NullPointerException();if(images!=null&&images.length!=strings.length)throw new IllegalArgumentException();for(int i=0;i<strings.length;i++)append(strings[i],images==null?null:images[i]);}
 public int size(){return choices.size();}public String getString(int i){return choices.getString(i);}public Image getImage(int i){return choices.getImage(i);}public int append(String s,Image im){return choices.append(s,im);}public void insert(int i,String s,Image im){choices.insert(i,s,im);}public void delete(int i){choices.delete(i);}public void deleteAll(){choices.deleteAll();}public void set(int i,String s,Image im){choices.set(i,s,im);}public boolean isSelected(int i){return choices.isSelected(i);}public int getSelectedIndex(){return choices.getSelectedIndex();}public int getSelectedFlags(boolean[] flags){return choices.getSelectedFlags(flags);}public void setSelectedIndex(int i,boolean b){choices.setSelectedIndex(i,b);}public void setSelectedFlags(boolean[] flags){choices.setSelectedFlags(flags);}public void setFitPolicy(int p){choices.setFitPolicy(p);}public int getFitPolicy(){return choices.getFitPolicy();}public void setFont(int i,Font f){choices.setFont(i,f);}public Font getFont(int i){return choices.getFont(i);}
 void render(Graphics g,int x,int y,int width){super.render(g,x,y,width);for(int i=0;i<size();i++)g.drawString((isSelected(i)?"[X] ":"[ ] ")+getString(i),x,y+18*(i+1),20);}int height(){return 20+18*size();}
}
